'use client';

import { useState } from 'react';

export function QuantityInput({ initial }: { initial: number }) {
  const [qty, setQty] = useState(initial);

  return (
    <div>
      <button onClick={() => setQty((q) => Math.max(0, q - 1))}>−</button>
      <output>{qty}</output>
      <button onClick={() => setQty((q) => q + 1)}>+</button>
    </div>
  );
}

